async def _ensure_client_exists(client_id: str) -> dict:
    user = await db.users.find_one({"id": client_id}, {"_id": 0, "full_name": 1, "company": 1, "phone": 1, "email": 1})
    if not user:
        raise HTTPException(status_code=404, detail="Client introuvable")
    return user


